/// Which Firebase project this app talks to, per platform.
///
/// Written by hand rather than generated by `flutterfire configure`, for
/// one reason: the generator writes `measurementId` into the web options,
/// which is the Google Analytics stream. We declare no tracking on the
/// Play data-safety form and in the privacy policy, and a field that
/// switches Analytics on would make both false. It is left out here, and
/// this comment is why — so that re-running the generator and quietly
/// reinstating it is a visible change rather than a silent one.
///
/// NONE OF THIS IS SECRET. A Firebase "apiKey" is not a credential: it
/// identifies the project to Google's endpoints and ships inside every
/// Android binary and every web bundle, where anyone can read it. What
/// stops somebody else using it is the Firestore rules (who may touch
/// which document) and the API-key restrictions in the Google Cloud
/// console (which app and which site may use the key at all). That is why
/// this file is committed and `key.properties` is not.
library;

import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show TargetPlatform, defaultTargetPlatform, kIsWeb;

/// Where the account data is held. Chosen when the project was created and
/// not changeable afterwards, so it is stated in the privacy policy too.
const String kFirestoreRegion = 'asia-southeast1';

class DefaultFirebaseOptions {
  const DefaultFirebaseOptions._();

  static FirebaseOptions get currentPlatform {
    if (kIsWeb) return web;
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      default:
        // iOS, macOS, Windows and Linux are not configured. The app runs
        // on Android and the web; a platform added later needs its own
        // app registered in the console, and failing loudly here is
        // better than connecting to the wrong project.
        throw UnsupportedError(
          'Firebase is configured for Android and the web only. '
          '$defaultTargetPlatform has no registered app.',
        );
    }
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyDKJk4ipiFheT3mq4iXlSDKBa-xDKJtoZQ',
    appId: '1:580314884974:android:54cdeb9a7895b572bd6f7f',
    messagingSenderId: '580314884974',
    projectId: 'intrinsic-e3abf',
    storageBucket: 'intrinsic-e3abf.firebasestorage.app',
  );

  static const FirebaseOptions web = FirebaseOptions(
    apiKey: 'AIzaSyDoTHjAPXuULT_usmYjh0TU7RB4Ly-ZK3o',
    appId: '1:580314884974:web:8392683a0ce97c72bd6f7f',
    messagingSenderId: '580314884974',
    projectId: 'intrinsic-e3abf',
    authDomain: 'intrinsic-e3abf.firebaseapp.com',
    storageBucket: 'intrinsic-e3abf.firebasestorage.app',
    // measurementId is deliberately absent. See the note at the top.
  );
}
